// studio_off_eeprom.ino — ESP32-S3: OFF только по настоящему нажатию кнопки
#include <WiFi.h>
#include <Preferences.h>

const char* WIFI_SSIDS[] = { "DIR-615T-0DBC", "KIBERone", "KIBERone5" };
const char* WIFI_PASSS[] = { "23233010", "KIBERone", "KIBERone" };
const int   NET_COUNT = 3;

const int   TCP_PORT    = 8085;
const int   UDP_PORT    = 8086;
const int   BUTTON      = 4;     // кнопка между GPIO4 и GND, подтяжка внутренняя
const int   WAIT_MS     = 15000;
const unsigned long DISCOVER_MS = 5000;
const int   MAX_PCS     = 20;

const unsigned long HOLD_DISCOVER = 3000; // держать 3 сек = режим обнаружения
const unsigned long DEBOUNCE_MS   = 80;   // пин должен держаться LOW столько, чтобы нажатие засчиталось

Preferences prefs;
WiFiUDP udp;
String ips[MAX_PCS];
int ipCount = 0;

bool connectTo(int idx) {
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(false);
  WiFi.begin(WIFI_SSIDS[idx], WIFI_PASSS[idx]);
  for (int t = 0; t < WAIT_MS / 500; t++) {
    if (WiFi.status() == WL_CONNECTED) return true;
    delay(500);
  }
  return false;
}

void saveIps() {
  prefs.begin("pcs", false);
  prefs.putInt("count", ipCount);
  for (int i = 0; i < ipCount; i++) {
    prefs.putString(("ip" + String(i)).c_str(), ips[i]);
  }
  prefs.end();
}

void loadIps() {
  ipCount = 0;
  prefs.begin("pcs", true);
  int n = prefs.getInt("count", 0);
  if (n > MAX_PCS) n = MAX_PCS;
  for (int i = 0; i < n; i++) {
    String s = prefs.getString(("ip" + String(i)).c_str(), "");
    if (s.length() > 0) ips[ipCount++] = s;
  }
  prefs.end();
}

void discoverPcs() {
  if (!connectTo(0)) return;

  udp.begin(UDP_PORT);
  for (int r = 0; r < 2; r++) {
    udp.beginPacket(IPAddress(255, 255, 255, 255), UDP_PORT);
    udp.print("WHOIS");
    udp.endPacket();
    delay(100);
  }

  unsigned long start = millis();
  char buf[64];
  while (millis() - start < DISCOVER_MS) {
    int len = udp.parsePacket();
    if (len > 0) {
      int n = udp.read(buf, 63);
      buf[n] = '\0';
      if (String(buf).startsWith("IAM:")) {
        String ip = udp.remoteIP().toString();
        bool already = false;
        for (int i = 0; i < ipCount; i++) if (ips[i] == ip) { already = true; break; }
        if (!already && ipCount < MAX_PCS) ips[ipCount++] = ip;
      }
    }
    delay(10);
  }
  udp.stop();
  saveIps();
}

void shutdownAll() {
  if (ipCount == 0) return;
  for (int i = 0; i < ipCount; i++) {
    WiFiClient client;
    if (client.connect(ips[i].c_str(), TCP_PORT, 2000)) {
      client.print("OFF\n");
      client.stop();
    }
  }
}

// стабильно ли LOW: пин должен быть LOW непрерывно DEBOUNCE_MS — так отсекаются помехи
bool buttonStablePressed() {
  if (digitalRead(BUTTON) != LOW) return false;
  delay(DEBOUNCE_MS);
  return digitalRead(BUTTON) == LOW;
}

void setup() {
  pinMode(BUTTON, INPUT_PULLUP); // подтяжка к 3.3V внутри чипа
  loadIps();
  connectTo(0);
}

void loop() {
  static bool wasDown = false;          // кнопка была зажата в прошлый проход
  static unsigned long downSince = 0;
  static bool actionDone = false;       // действие по этому нажатию уже выполнено

  bool isDown = buttonStablePressed();

  if (isDown && !wasDown) {             // момент: нажатие началось
    downSince = millis();
    actionDone = false;
  }

  if (isDown && wasDown && !actionDone) {
    if (millis() - downSince >= HOLD_DISCOVER) {
      discoverPcs();                    // держат 3+ сек — обнаружение, один раз за нажатие
      actionDone = true;
    }
  }

  if (!isDown && wasDown) {             // момент: кнопку отпустили
    if (!actionDone && millis() - downSince >= 100) {
      shutdownAll();                    // короткое нажатие — вырубить всех
    }
  }

  wasDown = isDown;

  if (WiFi.status() != WL_CONNECTED) connectTo(0);
  delay(10);
}
